                            print(f"  ✗ Grid mismatch for {det_name}")
                            grids_correct = False
                    else:
                        print(f"  ✗ Missing detector {det_name}")
                        grids_correct = False

                if grids_correct:
                    print("✓ All grids correct")
                else:
                    print("✗ Grid issues found")
                    all_passed = False
            else:
                print("✗ Detector mismatch")
                all_passed = False

        except Exception as e:
            print(f"✗ Exception occurred: {e}")
            import traceback
            traceback.print_exc()
            all_passed = False
        finally:
            os.unlink(temp_filename)

    return all_passed

